package com.aiservice.application.service;import com.aiservice.domain.exception.InvalidAiOutputException;import com.aiservice.domain.model.GeneratedQuestion;import java.util.*;import org.springframework.stereotype.Component;import tools.jackson.databind.*;
@Component public class StructuredOutputValidator{private final ObjectMapper mapper;public StructuredOutputValidator(ObjectMapper m){mapper=m;}public String validateQuestions(String json){try{JsonNode root=mapper.readTree(json);JsonNode items=root.isArray()?root:root.get("questions");if(items==null||!items.isArray()||items.isEmpty())throw new InvalidAiOutputException("questions array is required");Set<String> levels=Set.of("EASY","MEDIUM","HARD");for(JsonNode q:items){required(q,"question");required(q,"correctAnswer");required(q,"explanation");String difficulty=required(q,"difficulty");if(!levels.contains(difficulty))throw new InvalidAiOutputException("Invalid difficulty");JsonNode options=q.get("options");if(options==null||!options.isArray()||options.size()<2)throw new InvalidAiOutputException("At least two options required");Set<String> labels=new HashSet<>();for(JsonNode o:options){labels.add(required(o,"label"));required(o,"content");}if(!labels.contains(q.get("correctAnswer").asText()))throw new InvalidAiOutputException("correctAnswer must match an option label");}return mapper.writeValueAsString(items);}catch(InvalidAiOutputException e){throw e;}catch(Exception e){throw new InvalidAiOutputException("Malformed AI JSON",e);}}private String required(JsonNode n,String f){JsonNode v=n.get(f);if(v==null||!v.isTextual()||v.asText().isBlank())throw new InvalidAiOutputException(f+" is required");return v.asText();}}
